-- state_<schema>_<table>: each table's full contents as of the newest snapshot
-- carrying a `_SUCCESS` marker, chosen when the view is read.
--
-- These are the SNAPSHOT's rows, not the table's current state: changes after
-- the snapshot live in the `events` view.
-- To materialize a later point in time, use `bintrail reconstruct`. Folding
-- the deltas back onto a baseline is what that command does, and it is not
-- expressible as a view.
--
-- DECIMAL and NUMERIC columns are stored as text, so that a value MySQL can
-- hold is never rounded to fit a narrower type. The views below cast them
-- back to DECIMAL with the precision and scale the column was declared with,
-- so sum() and the rest work on them directly.
-- Columns wider than 38 digits have no DuckDB DECIMAL to be cast to, so they
-- stay text. They are named below. Cast them yourself when you need
-- arithmetic; DOUBLE works if an approximate result is acceptable.
-- Some files carry no column types, so their views cast nothing and every
-- decimal column in them reads as text. Those tables are named below. A
-- baseline older than this feature gains the casts when it is next taken or
-- refreshed; a PostgreSQL-source baseline stores all its values as text and
-- will not gain them. If a footer could not be read at all, the bintrail log
-- has the error.
-- The snapshot every state view below reads through, resolved once, when this
-- file is read. Re-run this statement to pick up a refresh without reopening
-- the session; every view follows it, so they never disagree about which
-- snapshot they are showing.
SET VARIABLE bintrail_newest_snapshot = (
  SELECT CASE WHEN max(file) IS NULL
    THEN error('bintrail views: no completed snapshot under s3://my-bucket/baselines/ (nothing there carries a _SUCCESS marker). Take or refresh a baseline, then read this file again.')
    ELSE max(regexp_replace(file, '_SUCCESS$', '')) END
  FROM glob('s3://my-bucket/baselines/*/_SUCCESS'));

-- Every table below has to still be in that snapshot. A table dropped at the
-- source leaves it, and DuckDB binds a view when it is created, so without
-- this the script would stop at that one view and never define the rest.
SET VARIABLE bintrail_missing_tables = (
  SELECT string_agg(t, ', ' ORDER BY t) FROM (VALUES
    ('Legacy-DB/Audit Log.parquet'),
    ('shop/order_items.parquet'),
    ('shop/orders.parquet'),
    ('shop_order/items.parquet')
  ) AS x(t)
  WHERE getvariable('bintrail_newest_snapshot') || t NOT IN (SELECT file FROM glob(getvariable('bintrail_newest_snapshot') || '**/*.parquet')));
SET VARIABLE bintrail_tables_checked = (SELECT CASE WHEN getvariable('bintrail_missing_tables') IS NOT NULL
  THEN error('bintrail views: these tables are not in the newest snapshot any more: ' || getvariable('bintrail_missing_tables') ||
    '. Looked in ' || getvariable('bintrail_newest_snapshot') ||
    '. If they were dropped or renamed, download this file again.') END);

